from PIL import Image
img = Image.open('/app/output/final_poster.png')
w, h = img.size

# Thorough scan: check every row at center column for non-bg, non-card color
print("Text/visual elements found at center column:")
found_sections = set()
for y in range(0, h, 2):
    p = img.getpixel((w//2, y))
    # Skip background and card background
    if p in [(10, 22, 38), (22, 35, 53), (28, 43, 62)]:
        continue
    r, g, b = p
    # Determine which section
    section = ""
    if y < 800:
        section = "TITLE"
    elif y < 2200:
        section = "HISTORICAL"
    elif y < 4500:
        section = "244-MILLION"
    elif y < 5800:
        section = "LEARNING-CRISIS"
    elif y < 7500:
        section = "INEQUALITY"
    elif y < 8600:
        section = "GENDER"
    else:
        section = "TAKEAWAY"
    if section not in found_sections:
        found_sections.add(section)
        print(f"  [{section:18s}] y={y:5d}: RGB=({r:3d},{g:3d},{b:3d})")

print(f"\nSections with visible content: {len(found_sections)} / 7")
# Check for missing sections
all_sections = {"TITLE", "HISTORICAL", "244-MILLION", "LEARNING-CRISIS", "INEQUALITY", "GENDER", "TAKEAWAY"}
missing = all_sections - found_sections
if missing:
    print(f"WARNING: Missing sections: {missing}")
else:
    print("All 7 sections have visible content ✓")

# Verify 244 million text is the largest
print("\n--- Largest text scan ---")
largest_span = 0
largest_y = 0
for y in range(0, h, 1):
    # Count consecutive non-bg pixels at this row
    span = 0
    for x in range(w//4, 3*w//4, 5):
        p = img.getpixel((x, y))
        if p not in [(10,22,38), (22,35,53), (28,43,62)]:
            span += 1
    if span > largest_span:
        largest_span = span
        largest_y = y

print(f"Largest horizontal content span: {largest_span*5}px at y={largest_y}")
PYEOF

